use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn process_node (symbol : & str , node : & serde_json :: Value , layer : & str) -> Result < (usize , String) > { let mut content = String :: new () ; let mut triple_count = 0 ; let node_id = format ! ("rustc:{}" , sanitize_id (symbol)) ; content . push_str (& format ! ("{} rdf:type lmdfb:RustcComponent ;\n" , node_id)) ; content . push_str (& format ! ("    lmdfb:hasSymbol \"{}\" ;\n" , symbol)) ; content . push_str (& format ! ("    lmdfb:belongsToLayer lmdfb:{}_layer ;\n" , layer)) ; triple_count += 3 ; if let Some (level) = node . get ("level") . and_then (| v | v . as_u64 ()) { content . push_str (& format ! ("    lmdfb:hasLevel {} ;\n" , level)) ; triple_count += 1 ; } if let Some (weight) = node . get ("weight") . and_then (| v | v . as_f64 ()) { content . push_str (& format ! ("    lmdfb:hasWeight {:.2} ;\n" , weight)) ; triple_count += 1 ; } if let Some (complexity) = node . get ("complexity_score") . and_then (| v | v . as_f64 ()) { content . push_str (& format ! ("    lmdfb:hasComplexity {:.2} ;\n" , complexity)) ; triple_count += 1 ; } if let Some (emoji) = node . get ("emoji") . and_then (| v | v . as_str ()) { content . push_str (& format ! ("    lmdfb:hasEmoji \"{}\" ;\n" , emoji)) ; triple_count += 1 ; } let semantic_class = classify_semantic_pattern (symbol) ; content . push_str (& format ! ("    lmdfb:hasSemanticPattern lmdfb:{} ;\n" , semantic_class)) ; triple_count += 1 ; let math_properties = extract_mathematical_properties (symbol , node) ; for prop in math_properties { content . push_str (& format ! ("    lmdfb:{} ;\n" , prop)) ; triple_count += 1 ; } content . push_str ("    .\n\n") ; Ok ((triple_count , content)) }